# Parameterized tests for various scenarios
@pytest.mark.parametrize(
    "username, password, expected_status",
    [
        ("test_user", "test_pass", 200),  # Valid credentials
        ("invalid_user", "wrong_pass", 400),  # Invalid credentials
        (None, None, 400),  # Missing credentials
    ]
)
def test_login_user(base_url, auth_headers, username, password, expected_status):
    """
    Test /user/login endpoint with various credentials.
    """
    params = {}
    if username is not None:
        params["username"] = username
    if password is not None:
        params["password"] = password

    response = requests.get(
        url=f"{base_url}/user/login", headers=auth_headers, params=params
    )

    assert response.status_code == expected_status

    if response.status_code == 200:
        # Validate response headers existence
        assert "X-Rate-Limit" in response.headers
        assert "X-Expires-After" in response.headers

        # Validate response content type
        assert response.headers.get("Content-Type") in [
            "application/xml",
            "application/json"
        ]

    elif response.status_code == 400:
        assert response.json().get("error") == "Invalid username/password supplied"

    else:
        # For unexpected errors
        pytest.fail(f"Unexpected status code: {response.status_code}")


